import pytest
from itsdangerous import TimestampSigner, BadTimeSignature, BadSignature

class ClockSigner(TimestampSigner):
    def __init__(self, now):
        self.now = now
        super().__init__('test-only-key')
    def get_timestamp(self):
        return self.now

def test_future_timestamp_is_rejected():
    token = ClockSigner(200).sign(b'payload')
    try:
        ClockSigner(100).unsign(token, max_age=60)
    except BadTimeSignature:
        return
    pytest.fail('FUTURE_TIMESTAMP_ACCEPTED')

def test_normal_timestamps_and_tamper():
    for age in (0, 20, 60):
        token = ClockSigner(100-age).sign(b'payload')
        assert ClockSigner(100).unsign(token, max_age=60) == b'payload'
        assert ClockSigner(100).unsign(token) == b'payload'
    old = ClockSigner(39).sign(b'payload')
    with pytest.raises(BadTimeSignature):
        ClockSigner(100).unsign(old, max_age=60)
    with pytest.raises(BadSignature):
        ClockSigner(100).unsign(old+b'tampered', max_age=60)
